    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    manifest = app.spec.manifest
    for resource in manifest:
        if resource.api_version == "v1":
            kind = resource.kind.lower()
            if kind in ["deployment", "replicaset"]:
                spec = {"observer_schema": {f"{kind}_condition": {"type": "object", "required": ["type", "status"]}}}
        elif resource.api_version == "apps/v1":
            kind = resource.kind.lower()
            if kind in ["deployment", "replicaset"]:
                spec = {"observer_schema": {f"{kind}_condition": {"type": "object", "required": ["type", "status"]}}}
                spec["observer_schema"][f"{kind}_condition"]["properties"] = {"type": {"type": "string", "enum": ["available", "unavailable"]}, "status": {"type": "boolean"}}
        elif resource.api_version == "batch/v1":
            kind = resource.kind.lower()
            if kind in ["job", "cronjob"]:
                spec = {"observer_schema": {f"{kind}_condition": {"type": "object", "required": ["type", "status"]}}}
                spec["observer_schema"][f"{kind}_condition"]["properties"] = {"type": {"type": "string", "enum": ["completed", "failed"]}, "status": {"type": "boolean"}}
