def _extract_number_and_supplment_from_issue_element(issue):
    """
    Extract the number and supplement information from the <issue> element of a PubMed Source document.
    """
    number, supplement = None, None
    issue = issue.strip()

    if not issue:
        return None, None

    if re.match(r'\d+', issue):
        number = issue
        supplement = None
    elif re.match(r'\d+ suppl\.? \d*', issue, re.IGNORECASE):
        number = re.match(r'\d+', issue).group(0)
        supplement = re.match(r'suppl\.\d*', issue, re.IGNORECASE).group(0)
    elif re.match(r'\d+ spe\d*', issue, re.IGNORECASE):
        number = re.match(r'\d+', issue).group(0)
        supplement = re.match(r'spe\d*', issue, re.IGNORECASE).group(0)
    elif re.match(r'suppl\.? \d*', issue, re.IGNORECASE):
        number = None
        supplement = re.match(r'suppl\.\d*', issue, re.IGNORECASE).group(0)
    elif re.match(r'supl\.? \d*', issue, re.IGNORECASE):
        number = None
        supplement = re.match(r'supl\.\d*', issue, re.IGNORECASE).group(0)
    else:
        raise ValueError(f'Unexpected issue format: {issue}')

    return number, supplement

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    result = []
    for i, arg in enumerate(args):
        if arg.op == OP.AND:
            if arg.args[0] == args[i + 1]:
                result.append(arg.args[0])
            elif arg.args[1] == args[i + 1]:
                result.append(arg.args[1])
        elif arg.op == OP.OR:
            if arg.args[0] == args[i + 1]:
                result.append(arg.args[1])
            elif arg.args[1] == args[i + 1]:
                result.append(arg.args[0])
        else:
            result.append(arg)
    return result

