def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """

    spec_defaults = self.spec.setdefaults(self._default_spec)
    args_defaults = self.args.setdefaults(spec_defaults)
    return {**args_defaults, **spec_defaults}

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    if command_name not in self._option_specs:
        return None
    command_spec = self._option_specs[command_name]
    for argument_spec in command_spec.arguments:
        if argument_spec.name == argument_name:
            return argument_spec
    return None

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided. """
    for arg in self.args:
        if arg.requires_arg and arg.name not in args:
            raise ValidationError(f"Missing required argument: {arg.name}")

def _get_conditionally_required_args(command_name, options_spec, args):
    required_args = []
    for option in options_spec:
        conditions = option.get('required_when')
        if conditions:
            for condition in conditions:
                if args.get(condition) == condition:
                    required_args.append(option['name'])
                    break
    return required_args

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    for arg in args:
        if len(args[arg]) > self.max_length:
            raise ValueError(f"Value of argument {arg} is longer than maximum length")

def validate_choice_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    for arg_name, arg_value in args.items():
        if arg_name in self.choices:
            valid_choices = self.choices[arg_name]
            if arg_value not in valid_choices:
                msg = "Invalid value for argument `{}`: `{}`. Available choices are: `{}`"
                raise ValueError(msg.format(arg_name, arg_value, valid_choices))

